#!/usr/bin/env node
/**
 * Regenerates the token reference block inside `apps/ui/DESIGN.md` ("Proof").
 *
 * The catalog is parsed straight from the installed design system so it can
 * never contain an invented token name and never drifts from the package:
 *   node_modules/@wordpress/theme/src/prebuilt/css/design-tokens.css
 * (Terrazzo-autogenerated — one description comment plus one
 * `--wpds-…: <light value>;` declaration per token). Color values shown are the
 * LIGHT values; the ThemeProvider derives dark values at runtime via color ramps
 * (colorjs.io), so they aren't static.
 *
 * App-local overrides (tokens this app redefines) are parsed from
 *   apps/ui/src/index.css
 * so the doc always reflects where we diverge from package defaults.
 *
 * Usage:
 *   node scripts/generate-design-tokens.mjs           # rewrite the block in place
 *   node scripts/generate-design-tokens.mjs --check   # exit 1 if the block is stale
 */

import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const SCRIPT_DIR = dirname( fileURLToPath( import.meta.url ) );
const UI_ROOT = join( SCRIPT_DIR, '..' );
const DESIGN_MD = join( UI_ROOT, 'DESIGN.md' );
const INDEX_CSS = join( UI_ROOT, 'src', 'index.css' );

const BEGIN = '<!-- BEGIN AUTOGENERATED: design tokens -->';
const END = '<!-- END AUTOGENERATED -->';

// Families in the order we want them rendered. Anything not listed here still
// renders, appended after these in first-seen order.
const FAMILY_ORDER = [
	'color',
	'typography',
	'dimension',
	'border',
	'elevation',
	'motion',
	'cursor',
];

// Color is large enough to warrant sub-grouping by layer (segment after `color`).
const COLOR_LAYER_ORDER = [ 'bg', 'fg', 'stroke' ];

const FAMILY_HEADINGS = {
	color: 'Color',
	typography: 'Typography',
	dimension: 'Dimension (spacing & sizing)',
	border: 'Border',
	elevation: 'Elevation',
	motion: 'Motion',
	cursor: 'Cursor',
};

const COLOR_LAYER_HEADINGS = {
	bg: 'Background (`bg`)',
	fg: 'Foreground (`fg`) — text & icons',
	stroke: 'Stroke (`stroke`) — borders & rings',
};

/** Walk up from `start` looking for `node_modules/<pkg>`. */
function resolvePackageDir( pkg, start ) {
	let dir = start;

	while ( true ) {
		const candidate = join( dir, 'node_modules', ...pkg.split( '/' ) );
		if ( existsSync( candidate ) ) {
			return candidate;
		}
		const parent = dirname( dir );
		if ( parent === dir ) {
			return null;
		}
		dir = parent;
	}
}

function findTokensCss() {
	const themeDir = resolvePackageDir( '@wordpress/theme', UI_ROOT );
	if ( ! themeDir ) {
		throw new Error( 'Could not find @wordpress/theme in node_modules. Run `npm install` first.' );
	}
	const cssPath = join( themeDir, 'src', 'prebuilt', 'css', 'design-tokens.css' );
	if ( ! existsSync( cssPath ) ) {
		throw new Error( `Token source not found at ${ cssPath }` );
	}
	return cssPath;
}

/**
 * Parse each description-comment + `--wpds-name: value;` declaration pair.
 * Returns [{ name, value, description, family, layer }].
 */
function parseTokens( css ) {
	const tokens = [];
	const lines = css.split( '\n' );
	let lastComment = '';
	for ( const raw of lines ) {
		const line = raw.trim();
		const comment = line.match( /^\/\*\s*(.*?)\s*\*\/$/ );
		if ( comment ) {
			lastComment = comment[ 1 ];
			continue;
		}
		const decl = line.match( /^(--wpds-[a-z0-9-]+)\s*:\s*(.+?);$/ );
		if ( decl ) {
			const name = decl[ 1 ];
			const segments = name.replace( /^--wpds-/, '' ).split( '-' );
			tokens.push( {
				name,
				value: decl[ 2 ].trim(),
				description: lastComment,
				family: segments[ 0 ],
				layer: segments[ 1 ] ?? '',
			} );
			lastComment = '';
		}
	}
	return tokens;
}

function escapeCell( text ) {
	return text.replace( /\|/g, '\\|' );
}

function table( rows ) {
	const out = [ '| Token | Value | Meaning |', '| --- | --- | --- |' ];
	for ( const { name, value, description } of rows ) {
		out.push(
			`| \`${ name }\` | \`${ escapeCell( value ) }\` | ${ escapeCell( description || '—' ) } |`
		);
	}
	return out.join( '\n' );
}

function orderedFamilies( tokens ) {
	const seen = [ ...new Set( tokens.map( ( t ) => t.family ) ) ];
	const ordered = FAMILY_ORDER.filter( ( f ) => seen.includes( f ) );
	for ( const f of seen ) {
		if ( ! ordered.includes( f ) ) {
			ordered.push( f );
		}
	}
	return ordered;
}

function renderColorFamily( tokens ) {
	const layers = [ ...new Set( tokens.map( ( t ) => t.layer ) ) ];
	const ordered = [
		...COLOR_LAYER_ORDER.filter( ( l ) => layers.includes( l ) ),
		...layers.filter( ( l ) => ! COLOR_LAYER_ORDER.includes( l ) ),
	];
	const parts = [];
	for ( const layer of ordered ) {
		const rows = tokens.filter( ( t ) => t.layer === layer );
		parts.push( `#### ${ COLOR_LAYER_HEADINGS[ layer ] ?? layer }` );
		parts.push( '' );
		parts.push( table( rows ) );
		parts.push( '' );
	}
	return parts.join( '\n' );
}

function parseOverrides( css ) {
	const rows = [];
	const lines = css.split( '\n' );
	let lastComment = '';
	let inComment = false;
	for ( const raw of lines ) {
		const line = raw.trim();
		// Track single- and multi-line comments to attach as context.
		if ( inComment ) {
			if ( line.includes( '*/' ) ) {
				inComment = false;
			}
			continue;
		}
		if ( line.startsWith( '/*' ) && line.includes( '*/' ) ) {
			lastComment = line.replace( /^\/\*\s*/, '' ).replace( /\s*\*\/$/, '' );
			continue;
		}
		if ( line.startsWith( '/*' ) ) {
			lastComment = line.replace( /^\/\*\s*/, '' );
			inComment = true;
			continue;
		}
		const decl = line.match( /^(--(?:wpds|wp-ui)-[a-z0-9-]+)\s*:\s*(.+?);$/ );
		if ( decl ) {
			rows.push( {
				name: decl[ 1 ],
				value: decl[ 2 ].trim(),
				note: lastComment,
			} );
		}
		if ( line !== '' && ! line.startsWith( '/*' ) ) {
			lastComment = '';
		}
	}
	return rows;
}

function renderOverrides( rows ) {
	if ( rows.length === 0 ) {
		return '_No app-local token overrides found in `src/index.css`._';
	}
	const out = [ '| Token | Overridden to | Why |', '| --- | --- | --- |' ];
	for ( const { name, value, note } of rows ) {
		out.push( `| \`${ name }\` | \`${ escapeCell( value ) }\` | ${ escapeCell( note || '—' ) } |` );
	}
	return out.join( '\n' );
}

function buildBlock() {
	const cssPath = findTokensCss();
	const tokens = parseTokens( readFileSync( cssPath, 'utf8' ) );
	const overrides = parseOverrides( readFileSync( INDEX_CSS, 'utf8' ) );

	const sections = [];
	sections.push(
		'> **Autogenerated — do not edit by hand.** Run `npm run gen:design-tokens`',
		'> from `apps/ui/` to refresh (e.g. after bumping `@wordpress/theme`). Source:',
		'> `@wordpress/theme/src/prebuilt/css/design-tokens.css`.',
		'>',
		'> Color **values are the light-theme values**. The ThemeProvider derives dark',
		'> values at runtime from color ramps, so there is no static dark value to list —',
		'> use the token, never a raw hex, and dark mode is handled for you.',
		''
	);

	sections.push( `_${ tokens.length } tokens._`, '' );

	for ( const family of orderedFamilies( tokens ) ) {
		const familyTokens = tokens.filter( ( t ) => t.family === family );
		sections.push( `### ${ FAMILY_HEADINGS[ family ] ?? family }`, '' );
		if ( family === 'color' ) {
			sections.push( renderColorFamily( familyTokens ) );
		} else {
			sections.push( table( familyTokens ), '' );
		}
	}

	sections.push(
		'### App-local overrides',
		'',
		'Tokens `apps/ui` redefines away from the package defaults (parsed from',
		'`src/index.css`). These win over the values above.',
		'',
		renderOverrides( overrides ),
		''
	);

	return sections
		.join( '\n' )
		.replace( /\n{3,}/g, '\n\n' )
		.trimEnd();
}

function main() {
	const check = process.argv.includes( '--check' );

	if ( ! existsSync( DESIGN_MD ) ) {
		throw new Error(
			`${ DESIGN_MD } does not exist. Create it with the ${ BEGIN } / ${ END } markers first.`
		);
	}

	const doc = readFileSync( DESIGN_MD, 'utf8' );
	const beginIdx = doc.indexOf( BEGIN );
	const endIdx = doc.indexOf( END );
	if ( beginIdx === -1 || endIdx === -1 || endIdx < beginIdx ) {
		throw new Error( `Could not find the marker pair in DESIGN.md:\n  ${ BEGIN }\n  ${ END }` );
	}

	const block = buildBlock();
	const before = doc.slice( 0, beginIdx + BEGIN.length );
	const after = doc.slice( endIdx );
	const next = `${ before }\n\n${ block }\n\n${ after }`;

	if ( check ) {
		if ( next !== doc ) {
			console.error( 'DESIGN.md token block is stale. Run `npm run gen:design-tokens`.' );
			process.exit( 1 );
		}
		console.log( 'DESIGN.md token block is up to date.' );
		return;
	}

	if ( next === doc ) {
		console.log( 'DESIGN.md token block already up to date.' );
		return;
	}
	writeFileSync( DESIGN_MD, next );
	console.log( 'Updated DESIGN.md token block.' );
}

main();
